$ErrorActionPreference = 'Stop'

function Read-Utf8NoBom([string]$Path) {
    $enc = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::ReadAllText($Path, $enc)
}

function Write-Utf8NoBom([string]$Path, [string]$Text) {
    $enc = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::WriteAllText($Path, $Text, $enc)
}

function Backup-Once([string]$Path) {
    $backup = "$Path.before-session-system.bak"
    if (-not (Test-Path $backup)) {
        Copy-Item $Path $backup -Force
    }
}

$root = (Get-Location).Path
$componentPath = Join-Path $root 'src\components\SessionControl.jsx'
$appPath = Join-Path $root 'src\App.jsx'
$devLayoutPath = Join-Path $root 'src\layouts\DeveloperLayout.jsx'
$portalLayoutPath = Join-Path $root 'src\clientPortal\components\UniversalDashboardShell.jsx'
$sessionApiPath = Join-Path $root 'api\auth\session.js'

foreach ($p in @($appPath,$devLayoutPath,$portalLayoutPath,$sessionApiPath)) {
    if (-not (Test-Path $p)) {
        throw "Required file not found: $p"
    }
}

New-Item -ItemType Directory -Force (Split-Path $componentPath) | Out-Null
$componentBytes = [Convert]::FromBase64String('')
[System.IO.File]::WriteAllBytes($componentPath, $componentBytes)

# Disable only the old App-level auto-timeout redirect.
# The new SessionControl owns inactivity UX and expiry.
Backup-Once $appPath
$app = Read-Utf8NoBom $appPath

$pattern = "(?s)(const handleLogout\s*=\s*useCallback\(\s*\(\s*isAutoTimeout\s*=\s*false\s*\)\s*=>\s*\{)"
$replacement = '$1' + "`r`n" + "      if (isAutoTimeout) {`r`n        window.dispatchEvent(new CustomEvent('bf-session-legacy-timeout'));`r`n        return;`r`n      }`r`n"
$patched = [regex]::Replace($app, $pattern, $replacement, 1)
if ($patched -eq $app) {
    throw 'Could not locate App.jsx handleLogout function.'
}
$app = $patched

$app = $app.Replace("const INACTIVITY_TIMEOUT_MS =`r`n    60 * 60 * 1000;", "const INACTIVITY_TIMEOUT_MS =`r`n    30 * 60 * 1000;")
$app = $app.Replace("const INACTIVITY_TIMEOUT_MS =`n    60 * 60 * 1000;", "const INACTIVITY_TIMEOUT_MS =`n    30 * 60 * 1000;")

Write-Utf8NoBom $appPath $app

function Patch-Countdown([string]$Path, [string]$ImportPath) {
    Backup-Once $Path
    $text = Read-Utf8NoBom $Path

    if (-not $text.Contains("SessionControl from")) {
        $text = "import SessionControl from '$ImportPath';`r`n" + $text
    }

    $start = $text.IndexOf('function SessionCountdown()')
    if ($start -lt 0) {
        throw "SessionCountdown not found in $Path"
    }

    $brace = $text.IndexOf('{', $start)
    if ($brace -lt 0) {
        throw "SessionCountdown opening brace not found in $Path"
    }

    $depth = 0
    $end = -1
    for ($i = $brace; $i -lt $text.Length; $i++) {
        if ($text[$i] -eq '{') {
            $depth++
        } elseif ($text[$i] -eq '}') {
            $depth--
            if ($depth -eq 0) {
                $end = $i + 1
                break
            }
        }
    }

    if ($end -lt 0) {
        throw "SessionCountdown closing brace not found in $Path"
    }

    $replacement = "function SessionCountdown() {`r`n  return <SessionControl />;`r`n}"
    $text = $text.Substring(0, $start) + $replacement + $text.Substring($end)
    Write-Utf8NoBom $Path $text
}

Patch-Countdown $devLayoutPath '../components/SessionControl'
Patch-Countdown $portalLayoutPath '../../components/SessionControl'

# Add POST TOUCH / EXTEND support to /api/auth/session.
Backup-Once $sessionApiPath
$api = Read-Utf8NoBom $sessionApiPath

if (-not $api.Contains('async function handleSessionActivityMutation')) {
    $helperText = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
    $handlerMarker = 'export default async function handler('
    $pos = $api.IndexOf($handlerMarker)
    if ($pos -lt 0) {
        throw 'Could not locate /api/auth/session handler.'
    }
    $api = $api.Insert($pos, $helperText + "`r`n`r`n")
}

if ($api.Contains("req.method !==`r`n    'GET'")) {
    $api = $api.Replace(
        "req.method !==`r`n    'GET'",
        "!['GET', 'POST'].includes(`r`n      req.method`r`n    )"
    )
} elseif ($api.Contains("req.method !==`n    'GET'")) {
    $api = $api.Replace(
        "req.method !==`n    'GET'",
        "!['GET', 'POST'].includes(`n      req.method`n    )"
    )
} elseif (-not $api.Contains("!['GET', 'POST'].includes")) {
    throw 'Could not update session API method guard.'
}

if (-not $api.Contains('SESSION ACTIVITY / EXTENSION')) {
    $marker = "  /* ========================================================`r`n     GET ONLY"
    $branch = @'
  /* ========================================================
     SESSION ACTIVITY / EXTENSION
  ======================================================== */

  if (
    req.method ===
    'POST'
  ) {
    return await handleSessionActivityMutation(
      req,
      res
    );
  }

'@
    if ($api.Contains($marker)) {
        $api = $api.Replace($marker, $branch + $marker)
    } else {
        $marker = "  /* ========================================================`n     GET ONLY"
        if ($api.Contains($marker)) {
            $api = $api.Replace($marker, $branch + $marker)
        } else {
            throw 'Could not insert POST session branch.'
        }
    }
}

Write-Utf8NoBom $sessionApiPath $api

Write-Host ''
Write-Host 'SUCCESS: Buddy Fleets MFA + inactivity session system patch applied.'
Write-Host 'Created: src\components\SessionControl.jsx'
Write-Host 'Updated: src\App.jsx'
Write-Host 'Updated: src\layouts\DeveloperLayout.jsx'
Write-Host 'Updated: src\clientPortal\components\UniversalDashboardShell.jsx'
Write-Host 'Updated: api\auth\session.js'
Write-Host 'Backups: *.before-session-system.bak'
